    "Claude Code 运行时显示 5 小时 / 每周配额（用 Claude Code 的登录凭据读官方 /usage，与 Claude 的 /usage 面板同值；首次会请求一次钥匙串访问授权），Codex 另含当前会话上下文占比；关闭只隐藏，不改动 Agent 配置": "Claude Code 実行中に 5 時間/週間クォータを表示（Claude Code のログイン資格情報で公式 /usage を読み取り、Claude の /usage パネルと同じ値。初回はキーチェーンアクセスの承認が必要）。Codex は現在のセッションコンテキスト割合も表示。オフにしても表示を隠すだけで Agent 設定は変更しない",
