    "「默认」项设定初始闪烁状态，但允许程序覆盖（DECSCUSR \\e[5 q / \\e[2 q、DEC mode 12）；「始终」项则固定光标、忽略程序控制。": "「デフォルト」は初期の点滅状態を設定するがプログラムによる上書きを許可（DECSCUSR \\e[5 q / \\e[2 q、DEC mode 12）。「常時」はカーソルを固定しプログラム制御を無視。",
