    "以手机浏览器的身份请求页面，站点便会返回为窄栏写的那套布局。关闭则请求桌面版；两种情况下页面都按面板自身的宽度排版。改动后该视图会重新加载。": "モバイルブラウザとしてページをリクエストし、サイトがナローカラムレイアウトを返すようにする。オフではデスクトップ版をリクエスト。いずれの場合もパネル自身の幅でレイアウトされる。変更後ビューが再読み込みされる。",
