    "Aster 运行时随时呼出或收起；隐藏后会话继续运行": "Invoquer ou masquer à tout moment pendant qu’Aster est en cours d’exécution ; les sessions continuent en arrière-plan",
    "Autocomplete 历史忽略模式": "Motif d’exclusion de l’historique Autocomplete",
    "Autocomplete 描述语言": "Langue des descriptions d’Autocomplete",
    "Bracketed Paste 视为安全": "Considérer le Bracketed Paste comme sûr",
    "Claude / Codex 等 hook 报告处理中时，屏幕上的权限提示可把状态改为等待输入": "Lorsqu’un hook Claude / Codex signale un traitement en cours, l’invite de permission à l’écran peut changer l’état en attente de saisie",
    "Claude Code 运行时显示 5 小时 / 每周配额（用 Claude Code 的登录凭据读官方 /usage，与 Claude 的 /usage 面板同值；首次会请求一次钥匙串访问授权），Codex 另含当前会话上下文占比；关闭只隐藏，不改动 Agent 配置": "Afficher le quota 5 heures / hebdomadaire pendant l’exécution de Claude Code (lit /usage officiel avec les identifiants de Claude Code — même valeur que le panneau /usage de Claude ; la première fois nécessite l’accès au trousseau). Codex affiche aussi le ratio de contexte de la session. Désactiver masque uniquement l’affichage sans modifier la configuration de l’Agent",
    "Codex 读全局 ~/.codex/config.toml，Aster 不会替你改它——复制下面的片段自行追加。": "Codex lit le fichier global ~/.codex/config.toml. Aster ne le modifiera pas pour vous — copiez le fragment ci-dessous et ajoutez-le vous-même.",
    "Control + 右键始终打开菜单": "Control + clic droit ouvre toujours le menu",
