    "本机 ssh 命令通过 OpenSSH ControlMaster 复用已认证连接；详情面板的远端文件与服务器监控借用它，不需要再次认证。只影响之后新建的终端": "Les commandes ssh locales réutilisent une connexion authentifiée via OpenSSH ControlMaster. Les fichiers distants et le moniteur serveur du panneau de détails l'empruntent, sans nouvelle authentification. S'applique uniquement aux terminaux créés ensuite",
