    "“记录中”会在本机保存命令、退出码与输出摘录；“隐身”与“关闭”都零落盘": "« Enregistrement » sauvegarde les commandes, codes de sortie et extraits de sortie localement ; « Incognito » et « Désactivé » n’écrivent rien sur le disque",
