    "「平滑」会让光标在同一行内移动时插值滑动，并在点击 / 聚焦时弹一下。": "« Lisse » fait glisser le curseur par interpolation lors d’un déplacement sur la même ligne, avec un léger rebond au clic ou au focus.",
    "「默认」项设定初始闪烁状态，但允许程序覆盖（DECSCUSR \\e[5 q / \\e[2 q、DEC mode 12）；「始终」项则固定光标、忽略程序控制。": "« Par défaut » définit l’état de clignotement initial mais permet aux programmes de le remplacer (DECSCUSR \\e[5 q / \\e[2 q, DEC mode 12) ; « Toujours » verrouille le curseur et ignore le contrôle des programmes.",
