    "从文件选择器挑一个目录加入排除列表": "Choisir un répertoire depuis le sélecteur de fichiers pour l’ajouter à la liste d’exclusion",
    "以手机浏览器的身份请求页面，站点便会返回为窄栏写的那套布局。关闭则请求桌面版；两种情况下页面都按面板自身的宽度排版。改动后该视图会重新加载。": "Demander les pages en tant que navigateur mobile pour que les sites renvoient leur disposition en colonne étroite. Désactivé, la version bureau est demandée ; dans les deux cas, la page est mise en page selon la largeur du panneau. La vue se recharge après modification.",
    "以预览 / 只读方式打开": "Ouvrir en aperçu / lecture seule",
    "任务出错时图标变红；点击 Dock 图标可跳转到出错的标签": "L’icône devient rouge en cas d’erreur ; cliquer sur l’icône du Dock pour accéder à l’onglet en erreur",
