    "会话结束后把事件流提炼成可复用的结论。本地规则式提炼始终启用；CLI Agent 提炼是可选增强。": "Distiller le flux d’événements en conclusions réutilisables après la fin d’une session. La distillation locale par règles est toujours active ; la distillation par Agent CLI est une amélioration facultative.",
    "会话结束后调用本机 Agent CLI 生成叙述性 Memory；这会把会话摘要发送到该 Agent 的云端": "Appeler l’Agent CLI local après la fin de la session pour générer une mémoire narrative ; cela envoie le résumé de session au cloud de cet Agent",
    "会话运行时会增加 CPU 和电量消耗": "Les sessions en cours augmentent la consommation CPU et énergétique",
    "会话运行时，图标中间的星芒持续旋转": "Le motif étoilé au centre de l’icône tourne en continu pendant l’exécution d’une session",
