    "保持登录状态": "Rester connecté",
    "随机标题颜色": "Couleurs de titre aléatoires",
    "新标签自动分配一个和其它标签不重样的标题颜色。关掉只影响自动色，右键标签手动设的颜色仍然保留——右键标签页的「标题颜色」可以挑色、换一个随机色或恢复默认。": "Attribue à chaque nouvel onglet une couleur de titre différente des autres. La désactivation masque seulement les couleurs automatiques — celles définies à la main sont conservées. Clic droit sur un onglet, menu « Couleur du titre » pour choisir une couleur, en tirer une autre au hasard ou rétablir la valeur par défaut.",
