    "把 cookie 和站点数据写到磁盘：关掉窗格、重启 Aster 之后仍然是登录态。关闭后改为只在内存里浏览——各个网页窗格之间仍然共用同一份会话，但最后一个网页窗格关掉就没了。只对之后新开的窗格生效。": "Écrire les cookies et données de site sur le disque : vous restez connecté après la fermeture des panneaux ou le redémarrage d’Aster. Désactivé, la navigation est en mémoire uniquement — les panneaux web partagent toujours la même session, mais elle disparaît lorsque le dernier se ferme. Ne s’applique qu’aux panneaux ouverts par la suite.",
    "把改过的 <id>.json 放进 ~/.config/aster/agent-detection 即可覆盖内置清单": "Placer un <id>.json modifié dans ~/.config/aster/agent-detection pour remplacer la liste intégrée",
