    "解析后命令与目录都相同的视图，在所有窗口中共用同一个运行中的程序——所以用了 ${cwd} 的视图每个目录一个。视图内的程序不能新建窗口、标签页、窗格，也不能打开 GUI 应用。": "Les vues dont la commande et le répertoire résolus sont identiques partagent un seul programme en cours d’exécution dans toutes les fenêtres — les vues utilisant ${cwd} en ont donc une par répertoire. Les programmes dans une vue ne peuvent pas créer de fenêtres, d’onglets, de panneaux ni ouvrir d’applications GUI.",
