    "画中画方式": "Mode Picture in Picture",
    "镜像沿用系统画中画，只能观看。可交互小窗把当前 Pane 的终端搬进置顶小窗，可以直接输入，终端网格随小窗变化；「跟随活动 Pane」始终使用镜像": "Le miroir utilise le Picture in Picture du système, en lecture seule. La fenêtre interactive déplace le terminal du Pane actuel dans une fenêtre flottante où vous pouvez saisir du texte ; la grille du terminal suit la taille de la fenêtre. « Suivre le Pane actif » utilise toujours le miroir",
