    "输入要识别的协议名称；不需要添加 ://。": "Saisissez le nom du protocole à reconnaître ; inutile d’ajouter ://.",
    "边缘窗口主轴占比；居中时同时调整宽高。呼出后可直接拖拽窗口边缘微调，尺寸会被记住": "Ratio de l’axe principal de la fenêtre de bord ; la largeur et la hauteur s’ajustent ensemble lorsqu’elle est centrée. Après l’appel, faites glisser les bords de la fenêtre pour ajuster ; la taille est mémorisée",
