    "运行 aster ignore 或使用“忘记此文件夹”时，同时从本地 zoxide 数据库移除该路径（如已安装 zoxide）": "Lors de l’exécution d’aster ignore ou de l’utilisation de « Oublier ce dossier », supprimer également le chemin de la base de données zoxide locale (si zoxide est installé)",
