    "逗号分隔的 glob；命中的命令不进入本机学习": "Globs séparés par des virgules ; les commandes correspondantes sont exclues de l’apprentissage local",
    "逗号分隔的命令名；命中的命令连同它的输出都不记录。op、vault、pass、gpg、security 已内置排除": "Noms de commande séparés par des virgules ; les commandes correspondantes et leur sortie ne sont pas enregistrées. op, vault, pass, gpg, security sont exclus par défaut",
    "逗号分隔的绝对路径；这些目录下的活动从不写入数据库。~/.ssh、~/.gnupg、~/.aws、~/.kube、~/.password-store 已内置排除": "Chemins absolus séparés par des virgules ; l’activité sous ces répertoires n’est jamais écrite dans la base de données. ~/.ssh, ~/.gnupg, ~/.aws, ~/.kube, ~/.password-store sont exclus par défaut",
    "逗号分隔；按命令 token 前缀识别长任务，留空即关闭": "Séparés par des virgules ; identifier les tâches longues par préfixe de jeton de commande. Laissez vide pour désactiver",
