    "重试": "Erneut versuchen",
    "+ 添加应用": "+ App hinzufügen",
    "Agent 完成任务后发送系统通知": "Systembenachrichtigung senden, wenn der Agent eine Aufgabe abschließt",
    "Agent 工作时保持 macOS 唤醒": "macOS wach halten, während der Agent arbeitet",
    "Agent 执行任务期间显示状态": "Status anzeigen, während der Agent arbeitet",
