    "Agent 等待用户时发送系统通知": "Systembenachrichtigung senden, wenn der Agent auf den Benutzer wartet",
    "Aster 不在前台时，收到通知则让 Dock 图标持续跳动，切回 Aster 即停": "Dock-Symbol dauerhaft hüpfen lassen, wenn eine Benachrichtigung eintrifft, während Aster im Hintergrund ist; stoppt beim Zurückwechseln",
    "Aster 可编辑配置文件": "Editierbare Aster-Konfigurationsdateien",
    "Aster 处于前台时横幅的显示行为": "Bannerverhalten, wenn Aster im Vordergrund ist",
