    "Autocomplete 描述语言": "Autocomplete-Beschreibungssprache",
    "Bracketed Paste 视为安全": "Bracketed Paste als sicher behandeln",
    "Claude / Codex 等 hook 报告处理中时，屏幕上的权限提示可把状态改为等待输入": "Wenn ein Claude-/Codex-Hook die Verarbeitung meldet, kann eine Berechtigungsanfrage auf dem Bildschirm den Status auf „Eingabe erwartet“ ändern",
    "Claude Code 运行时显示 5 小时 / 每周配额（用 Claude Code 的登录凭据读官方 /usage，与 Claude 的 /usage 面板同值；首次会请求一次钥匙串访问授权），Codex 另含当前会话上下文占比；关闭只隐藏，不改动 Agent 配置": "Während Claude Code läuft, das 5-Stunden-/Wochenkontingent anzeigen (liest /usage mit Claude-Code-Anmeldedaten — gleicher Wert wie im Claude-/usage-Panel; beim ersten Mal wird Schlüsselbundzugriff benötigt). Codex zeigt zusätzlich den Sitzungskontext-Anteil. Ausschalten blendet nur die Anzeige aus, ändert die Agent-Einstellungen nicht",
    "Codex 读全局 ~/.codex/config.toml，Aster 不会替你改它——复制下面的片段自行追加。": "Codex liest die globale ~/.codex/config.toml. Aster ändert sie nicht für Sie — kopieren Sie das Snippet unten und fügen Sie es selbst hinzu.",
