    "本机 ssh 命令通过 OpenSSH ControlMaster 复用已认证连接；详情面板的远端文件与服务器监控借用它，不需要再次认证。只影响之后新建的终端": "Lokale ssh-Befehle verwenden über OpenSSH ControlMaster eine bereits authentifizierte Verbindung erneut. Remote-Dateien und Server-Monitor im Detailbereich nutzen sie mit, eine erneute Authentifizierung entfällt. Gilt nur für danach erstellte Terminals",
