    "~/.config/aster/views/<名称>": "~/.config/aster/views/<Name>",
    "“记录中”会在本机保存命令、退出码与输出摘录；“隐身”与“关闭”都零落盘": "„Aufzeichnung“ speichert Befehle, Exitcodes und Ausgabeauszüge lokal; „Inkognito“ und „Aus“ schreiben nichts auf die Festplatte",
