    "、": ", ",
    "「平滑」会让光标在同一行内移动时插值滑动，并在点击 / 聚焦时弹一下。": "„Glatt“ lässt den Cursor bei Bewegung innerhalb einer Zeile gleiten und beim Klicken/Fokussieren leicht federn.",
    "「默认」项设定初始闪烁状态，但允许程序覆盖（DECSCUSR \\e[5 q / \\e[2 q、DEC mode 12）；「始终」项则固定光标、忽略程序控制。": "„Standard“ setzt den anfänglichen Blinkstatus, lässt aber Programmüberschreibung zu (DECSCUSR \\e[5 q / \\e[2 q, DEC-Modus 12); „Immer“ fixiert den Cursor und ignoriert Programmsteuerung.",
    "上下文菜单": "Kontextmenü",
