    "从不提示": "Nie nachfragen",
    "从屏幕边缘或居中显示": "Vom Bildschirmrand oder zentriert anzeigen",
    "从文件选择器挑一个目录加入排除列表": "Ein Verzeichnis aus dem Dateiauswahldialog auswählen und zur Ausschlussliste hinzufügen",
    "以手机浏览器的身份请求页面，站点便会返回为窄栏写的那套布局。关闭则请求桌面版；两种情况下页面都按面板自身的宽度排版。改动后该视图会重新加载。": "Seiten als mobiler Browser anfordern, damit Websites ihr schmales Layout liefern. Wenn deaktiviert, wird die Desktop-Version angefordert; in beiden Fällen wird die Seite in der Breite des Panels dargestellt. Die Ansicht wird nach der Änderung neu geladen.",
    "以预览 / 只读方式打开": "In Vorschau / Nur-Lesen öffnen",
    "任务出错时图标变红；点击 Dock 图标可跳转到出错的标签": "Symbol wird bei Aufgabenfehler rot; Klick auf das Dock-Symbol springt zum fehlerhaften Tab",
    "任务完成时通知": "Bei Aufgabenabschluss benachrichtigen",
    "任务完成显示角标": "Badge bei Aufgabenabschluss anzeigen",
    "任务进行时旋转": "Während der Aufgabe drehen",
    "优先级 {n}": "Priorität {n}",
    "会话恢复": "Sitzungswiederherstellung",
    "会话日志": "Sitzungsprotokoll",
    "会话日志上限": "Sitzungsprotokoll-Obergrenze",
    "会话结束后把事件流提炼成可复用的结论。本地规则式提炼始终启用；CLI Agent 提炼是可选增强。": "Den Ereignisstrom nach Sitzungsende in wiederverwendbare Schlussfolgerungen destillieren. Lokale regelbasierte Destillation ist immer aktiv; CLI-Agent-Destillation ist eine optionale Erweiterung.",
    "会话结束后调用本机 Agent CLI 生成叙述性 Memory；这会把会话摘要发送到该 Agent 的云端": "Nach Sitzungsende den lokalen Agent-CLI aufrufen, um narrative Memory zu generieren; dies sendet die Sitzungszusammenfassung an die Cloud des Agents",
    "会话运行时会增加 CPU 和电量消耗": "Laufende Sitzungen erhöhen den CPU- und Stromverbrauch",
    "会话运行时，图标中间的星芒持续旋转": "Der Sternenkranz in der Mitte des Symbols dreht sich fortlaufend, während eine Sitzung läuft",
