    "保存并重放标签页、分屏、命令和文本片段。": "Tabs, Teilungen, Befehle und Textfragmente speichern und wiedergeben.",
    "保持登录状态": "Angemeldet bleiben",
    "随机标题颜色": "Zufällige Titelfarben",
    "新标签自动分配一个和其它标签不重样的标题颜色。关掉只影响自动色，右键标签手动设的颜色仍然保留——右键标签页的「标题颜色」可以挑色、换一个随机色或恢复默认。": "Weist jedem neuen Tab eine Titelfarbe zu, die sich von den anderen unterscheidet. Beim Ausschalten entfallen nur die automatischen Farben – manuell gesetzte Farben bleiben. Über Rechtsklick auf einen Tab lässt sich unter „Titelfarbe“ eine Farbe wählen, neu auswürfeln oder zurücksetzen.",
    "保留 Recipe、主题文件和工作区文件": "Recipes, Design-Dateien und Arbeitsbereich-Dateien beibehalten",
    "信息": "Info",
    "信息、大纲、Git、文件、记忆与自定义视图的显示与顺序": "Anzeige und Reihenfolge von Info, Gliederung, Git, Dateien, Erinnerungen und benutzerdefinierten Ansichten",
    "修改覆盖清单后重新读取；已运行的 Agent 会话不受影响": "Nach Änderung der Überschreibungslisten neu einlesen; bereits laufende Agent-Sitzungen sind nicht betroffen",
