    "只移除每个物理行末尾空白": "Nur Leerzeichen am Ende jeder physischen Zeile entfernen",
    "可选的可执行文件、wrapper 与全局参数；Aster 会自动追加原生 resume / fork 参数，留空恢复默认。": "Optionale ausführbare Datei, Wrapper und globale Argumente; Aster hängt automatisch native resume-/fork-Argumente an. Leer lassen, um die Standardwerte wiederherzustellen.",
    "可重新运行的命令，按逗号分隔的前缀匹配": "Erneut ausführbare Befehle, abgeglichen durch kommagetrennte Präfixe",
    "右侧": "Rechts",
    "右键动作": "Rechtsklick-Aktion",
    "合并": "Kombiniert",
    "合并时标签页上只有一个指示位：平时显示你的图标，有状态发生时由角标接管。分开时图标在左、角标在右，并隐藏 shell 名称——分屏标签页仍会显示窗格数。": "Im zusammengeführten Modus hat der Tab nur einen Indikatorplatz: Normalerweise wird Ihr Symbol angezeigt, bei einem Status übernimmt das Badge. Im getrennten Modus ist das Symbol links und das Badge rechts, der Shell-Name wird ausgeblendet — geteilte Tabs zeigen weiterhin die Bereichsanzahl.",
    "合成": "Synthetisch",
    "名称": "Name",
    "后台命令完成时发送通知": "Benachrichtigung senden, wenn ein Hintergrundbefehl abgeschlossen ist",
    "后台静默下载，退出 Aster 后自动完成安装": "Im Hintergrund leise herunterladen; die Installation wird nach dem Beenden von Aster automatisch abgeschlossen",
    "向子进程声明的“终端类型”。Auto 是安全的默认值，优先使用内置 xterm-ghostty，缺条目回退 xterm-256color": "An Kindprozesse deklarierter Terminaltyp. Auto ist der sichere Standard: bevorzugt das integrierte xterm-ghostty, fällt auf xterm-256color zurück, wenn der Eintrag fehlt",
    "向文件和文件夹菜单添加第三方应用": "Drittanbieter-Apps zu Datei- und Ordnermenüs hinzufügen",
    "启动、窗口行为和 macOS 系统集成。": "Start, Fensterverhalten und macOS-Systemintegration.",
    "启动命令": "Startbefehl",
    "启动时": "Beim Start",
    "启用“省略 aster 前缀”或“自定义别名”时，覆盖你已定义的 edit/view/jump 等 shell 函数，而非保留原定义": "Wenn „aster-Präfix weglassen“ oder „Benutzerdefinierte Aliase“ aktiviert ist, vorhandene edit/view/jump-Shell-Funktionen überschreiben, statt die Originale beizubehalten",
    "启用“选中即复制”时，选区会保留，因此此项不可用": "Wenn „Auswahl kopieren“ aktiviert ist, bleibt die Auswahl erhalten, daher ist diese Option nicht verfügbar",
    "命令": "Befehl",
