    "把 Aster 的项目记忆接给 Agent，让它们查得到这个项目过去发生了什么。": "Asters Projekterinnerungen mit Agents verbinden, damit sie nachsehen können, was in diesem Projekt passiert ist.",
    "把 cookie 和站点数据写到磁盘：关掉窗格、重启 Aster 之后仍然是登录态。关闭后改为只在内存里浏览——各个网页窗格之间仍然共用同一份会话，但最后一个网页窗格关掉就没了。只对之后新开的窗格生效。": "Cookies und Website-Daten auf die Festplatte schreiben: Sie bleiben nach dem Schließen von Bereichen oder dem Neustart von Aster angemeldet. Wenn deaktiviert, wird nur im Speicher gesurft — Webbereiche teilen sich weiterhin dieselbe Sitzung, aber sie ist weg, wenn der letzte geschlossen wird. Gilt nur für danach geöffnete Bereiche.",
