    "解析后命令与目录都相同的视图，在所有窗口中共用同一个运行中的程序——所以用了 ${cwd} 的视图每个目录一个。视图内的程序不能新建窗口、标签页、窗格，也不能打开 GUI 应用。": "Ansichten, deren aufgelöster Befehl und Verzeichnis identisch sind, teilen ein laufendes Programm über alle Fenster — Ansichten mit ${cwd} erhalten daher eine pro Verzeichnis. Programme innerhalb einer Ansicht können keine Fenster, Tabs, Bereiche erstellen oder GUI-Apps öffnen.",
