    "镜像沿用系统画中画，只能观看。可交互小窗把当前 Pane 的终端搬进置顶小窗，可以直接输入，终端网格随小窗变化；「跟随活动 Pane」始终使用镜像": "Spiegeln verwendet das System-Bild-in-Bild und ist nur zum Ansehen. Das interaktive Fenster verschiebt das Terminal des aktuellen Pane in ein schwebendes Fenster mit direkter Eingabe; das Terminalraster folgt der Fenstergröße. „Aktivem Pane folgen“ verwendet immer Spiegeln",
