    "边缘窗口主轴占比；居中时同时调整宽高。呼出后可直接拖拽窗口边缘微调，尺寸会被记住": "Hauptachsenverhältnis des Randfensters; Breite und Höhe werden bei zentrierter Ausrichtung gemeinsam angepasst. Nach dem Aufrufen lassen sich die Fensterkanten ziehen; die Größe wird gespeichert",
